CREATE OR REPLACE FUNCTION public.transition_gateway_transaction_status(p_transaction_id uuid,p_user_id uuid,p_next_status text,p_failure_code text DEFAULT NULL::text,p_external_id text DEFAULT NULL::text) RETURNS public.gateway_transactions LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $function$ DECLARE v_row public.gateway_transactions; v_next text := lower(trim(coalesce(p_next_status,''))); BEGIN IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'forbidden'; END IF; IF v_next NOT IN ('created','pending','approved','failed','refunded','chargeback') THEN RAISE EXCEPTION 'invalid_status'; END IF; UPDATE public.gateway_transactions t SET status = CASE WHEN t.status = 'created' AND v_next IN ('created','pending','approved','failed') THEN v_next WHEN t.status = 'pending' AND v_next IN ('pending','approved','failed') THEN v_next WHEN t.status = 'approved' AND v_next IN ('approved','refunded','chargeback') THEN v_next WHEN t.status = 'failed' AND v_next = 'failed' THEN v_next WHEN t.status = 'refunded' AND v_next = 'refunded' THEN v_next WHEN t.status = 'chargeback' AND v_next = 'chargeback' THEN v_next ELSE t.status END, failure_code = coalesce(nullif(p_failure_code,''), t.failure_code), external_id = coalesce(nullif(p_external_id,''), t.external_id), completed_at = CASE WHEN v_next IN ('approved','failed','refunded','chargeback') THEN coalesce(t.completed_at, now()) ELSE t.completed_at END, updated_at = now() WHERE t.id = p_transaction_id AND t.user_id = p_user_id RETURNING t.* INTO v_row; IF NOT FOUND THEN RAISE EXCEPTION 'transaction_not_found'; END IF; IF v_row.status <> v_next THEN RAISE EXCEPTION 'invalid_status_transition'; END IF; RETURN v_row; END; $function$;